select
  'chemical-biology-and-bioorganic-chemistry',
  null,
  'Chemical Biology and Bioorganic Chemistry',
  'Chemical Biology and Bioorganic Chemistry',
  'This graduate course trains students to use chemical principles, molecular design, and quantitative biological evidence to understand and control living systems. It treats chemical biology and bioorganic chemistry as a single integrated practice: mechanisms and structure-reactivity relationships are used to design probes, perturb pathways, measure biological state, and evaluate therapeutic potential. The syllabus intentionally extends topics with modern structural biology, chemical proteomics, spatial-temporal cellular control, systems chemical biology, and reproducibility standards. These additions make the course suitable for a research-intensive MS Chemistry program and for students preparing for chemical biology, medicinal chemistry, biotechnology, pharmaceutical science, or interdisciplinary life-science research.',
  $cbbcjson${"slug": "chemical-biology-and-bioorganic-chemistry", "title": "Chemical Biology and Bioorganic Chemistry", "description": "This graduate course trains students to use chemical principles, molecular design, and quantitative biological evidence to understand and control living systems. It treats chemical biology and bioorganic chemistry as a single integrated practice: mechanisms and structure-reactivity relationships are used to design probes, perturb pathways, measure biological state, and evaluate therapeutic potential. The syllabus intentionally extends topics with modern structural biology, chemical proteomics, spatial-temporal cellular control, systems chemical biology, and reproducibility standards. These additions make the course suitable for a research-intensive MS Chemistry program and for students preparing for chemical biology, medicinal chemistry, biotechnology, pharmaceutical science, or interdisciplinary life-science research.", "topics": [{"id": "8aa8a3f3-6d40-459e-b97e-cb44d8d7eb80", "type": "topic", "title": "Foundations of Chemical Biology and Bioorganic Chemistry", "description": "This opening unit frames chemical biology as an experimental way of asking biological questions with molecular tools. Students learn what distinguishes probe design, perturbation, and mechanism-first thinking from descriptive biology or synthesis alone.", "children": [{"id": "1c7f4ca5-919a-4c71-b19f-45d2969c3016", "type": "subtopic", "title": "Field Scope and Research Questions", "description": "Students learn to convert broad biological problems into tractable molecular questions.", "children": [{"id": "e79da936-e1f1-45e2-895a-910a799aeccd", "type": "concept", "title": "Chemical biology vs. biochemistry, molecular biology, medicinal chemistry, and synthetic biology"}, {"id": "d856b58d-3676-45b1-94cd-230f8cee9543", "type": "concept", "title": "Probe, target, pathway, phenotype, and mechanism as working units"}, {"id": "2b0e1bf2-4937-4702-86b2-2caf7c557e2e", "type": "concept", "title": "Choosing when a chemical approach is more powerful than a genetic or purely biochemical approach"}]}, {"id": "76c09871-9024-4d57-852b-7586525846a8", "type": "subtopic", "title": "Bioorganic Logic in Living Systems", "description": "This subtopic connects structure and reactivity to the behavior of biomolecules in water, cells, and tissues.", "children": [{"id": "22dc89ea-668b-42ae-8774-57d34e33e721", "type": "concept", "title": "Functional groups and reaction manifolds common in biomolecules"}, {"id": "d7cde8ca-82ea-4407-aff1-3b4a9bc39a83", "type": "concept", "title": "Selectivity, kinetics, reversibility, and compatibility with biological media"}, {"id": "65689326-cabb-4106-92d9-62675ded7578", "type": "concept", "title": "How pH, solvation, compartment, and concentration change chemical outcomes"}]}, {"id": "790378a5-db4a-46c1-8bef-2ff28708b077", "type": "subtopic", "title": "Experimental Design and Evidence Standards", "description": "Students practice judging whether a chemical tool really supports the biological claim being made.", "children": [{"id": "aceb97ea-0458-491d-8719-04b65534cb07", "type": "concept", "title": "Controls for activity, specificity, toxicity, and localization"}, {"id": "81724f50-1db3-4621-b435-da42e1abf604", "type": "concept", "title": "Dose-response, time-course, rescue, and orthogonal validation"}, {"id": "4383bf45-9869-4a72-8991-4c209633b8ba", "type": "concept", "title": "Common failure modes: promiscuity, assay interference, aggregation, and off-target biology"}]}]}, {"id": "9c978524-0ff0-4c48-b364-ee817fa58bd9", "type": "topic", "title": "Biomolecular Structure, Recognition, and Noncovalent Interactions", "description": "Chemical biology depends on understanding molecular recognition with enough precision to design experiments. This unit teaches students to read structure, binding, and dynamics as a design language for probes and interventions.", "children": [{"id": "7567e1dc-76e3-4bc5-97bc-306a61058c35", "type": "subtopic", "title": "Protein Structure and Dynamics", "description": "The goal is to see proteins as flexible chemical systems rather than static cartoons.", "children": [{"id": "be9131bd-27e7-4c5d-aa64-f09ac5abba93", "type": "concept", "title": "Primary through quaternary structure and intrinsically disordered regions"}, {"id": "4960465e-d667-4602-b23c-c6eb4d460fd3", "type": "concept", "title": "Active sites, allostery, conformational selection, and induced fit"}, {"id": "d0314c4d-ba3c-48f3-a5d1-f55d9fe2fedc", "type": "concept", "title": "Using RCSB Protein Data Bank structures to reason about function"}]}, {"id": "60ef59f0-7e3b-4c1d-898b-484dcbbb6053", "type": "subtopic", "title": "Ligand Binding and Molecular Recognition", "description": "Students learn the forces that make binding strong, selective, and biologically meaningful.", "children": [{"id": "951a1bd9-1488-414e-80a6-fb61edb7f14a", "type": "concept", "title": "Hydrogen bonding, electrostatics, hydrophobic effects, cation-pi and pi-stacking interactions"}, {"id": "134c68c7-b03f-4319-aa0a-2d49fdf57804", "type": "concept", "title": "Affinity, residence time, cooperativity, and competition"}, {"id": "1fbbbfff-25c9-403f-9d3f-cd1cde692253", "type": "concept", "title": "Thermodynamic vs. kinetic control in protein-ligand systems"}]}, {"id": "7ba69a52-df79-4de0-9791-5ea80a7c551f", "type": "subtopic", "title": "Structural Methods for Chemical Biology", "description": "This section explains how structural evidence is produced and what its limits are.", "children": [{"id": "25bd82ce-5638-40f8-b1eb-6091c5bb4436", "type": "concept", "title": "X-ray crystallography, NMR, cryo-EM, mass spectrometry, and computational models"}, {"id": "bb893eea-493e-4e13-a00f-2643052b748b", "type": "concept", "title": "Resolution, model uncertainty, occupancy, and alternate conformations"}, {"id": "09f5151e-c5e1-4a1d-a21c-996360afb493", "type": "concept", "title": "Using structural data without overclaiming biological mechanism"}]}]}, {"id": "d0d3fa63-e9e5-4900-8b78-e2db70c1195d", "type": "topic", "title": "Enzyme Mechanisms, Catalysis, and Bioorganic Reactivity", "description": "Enzymes are central objects in bioorganic chemistry because they reveal how biological systems accelerate and control reactions. Students learn to connect kinetic data, mechanistic hypotheses, and inhibitor design.", "children": [{"id": "97519fe7-38ca-4ce4-9f69-19f7e068fb05", "type": "subtopic", "title": "Kinetics and Catalytic Mechanisms", "description": "Students learn the quantitative vocabulary needed to interpret enzyme behavior.", "children": [{"id": "f36ce2dc-dabf-4705-8632-701aba711013", "type": "concept", "title": "Michaelis-Menten analysis, steady-state assumptions, kcat, KM, and catalytic efficiency"}, {"id": "b1af27b5-0eb7-42fb-8932-a28025cd2d89", "type": "concept", "title": "Pre-steady-state kinetics, isotope effects, pH-rate profiles, and saturation behavior"}, {"id": "32fcdb1b-7042-42d4-9148-237e2b8e82d3", "type": "concept", "title": "General acid-base, covalent, metal-ion, proximity, and electrostatic catalysis"}]}, {"id": "b6507fc4-40c3-431e-871d-a7af2e7d066b", "type": "subtopic", "title": "Inhibition and Mechanism-Based Inactivators", "description": "The point is to distinguish reversible modulation from covalent or time-dependent enzyme capture.", "children": [{"id": "bdec1794-e9fc-471c-a946-0c09413c7382", "type": "concept", "title": "Competitive, noncompetitive, uncompetitive, mixed, tight-binding, and slow-binding inhibition"}, {"id": "7f1557a7-7f0c-489e-ab1f-d218c442e843", "type": "concept", "title": "Covalent inhibitors, suicide substrates, electrophile tuning, and warhead selectivity"}, {"id": "97de081d-3de3-4c20-8d76-704671cafabe", "type": "concept", "title": "Interpreting IC50, Ki, kinact/KI, and target engagement data"}]}, {"id": "a1412aff-5fd1-4e42-b49f-d4f0640adb93", "type": "subtopic", "title": "Transition-State and Cofactor Chemistry", "description": "This subtopic shows how enzyme chemistry can inspire both probes and therapeutics.", "children": [{"id": "3e5e7b51-beec-49ac-9eb1-2fb43d37eb30", "type": "concept", "title": "Transition-state analogs and catalytic antibodies"}, {"id": "45d55814-a478-45b7-a2e1-4059552bef10", "type": "concept", "title": "PLP, NAD(P)H, flavins, biotin, thiamine pyrophosphate, SAM, and metal cofactors"}, {"id": "7db045c9-dbc7-4dc2-8f39-dc8051271a1c", "type": "concept", "title": "Radical, redox, methyl-transfer, acyl-transfer, and group-transfer mechanisms"}]}]}, {"id": "169fede5-5302-40cc-b942-606291a7c3d1", "type": "topic", "title": "Protein Chemistry, Modification, and Chemical Genetics", "description": "Proteins are both targets and tools in chemical biology. This unit builds fluency in modifying proteins, perturbing functions, and using chemical-genetic logic to assign mechanism.", "children": [{"id": "8996863f-f4de-4100-a21a-540ca6250da9", "type": "subtopic", "title": "Protein Modification and Bioconjugation", "description": "Students learn how to install chemical functionality while preserving biological meaning.", "children": [{"id": "5c73d207-f306-4946-abc8-bb5c1c8b9619", "type": "concept", "title": "Lysine, cysteine, N-terminus, tyrosine, methionine, and unnatural amino acid labeling"}, {"id": "fde1c745-3c89-4e16-ac5b-e16bb10f2b32", "type": "concept", "title": "Site-selective vs. residue-selective strategies and stoichiometry control"}, {"id": "22d56650-14b8-471e-acfd-8d3663271179", "type": "concept", "title": "Stability, activity retention, purification, and analytical confirmation"}]}, {"id": "d0f2359d-20e7-4c16-ba7d-2d737ebfa70c", "type": "subtopic", "title": "Post-Translational Modifications", "description": "This subtopic treats PTMs as dynamic chemical signals that regulate protein function.", "children": [{"id": "23eea951-1ed6-4d3a-b80e-ad07d82b03e7", "type": "concept", "title": "Phosphorylation, acetylation, methylation, ubiquitination, SUMOylation, glycosylation, lipidation, and redox PTMs"}, {"id": "1980e417-dc56-4e5e-aec5-24d9e55e0670", "type": "concept", "title": "Writers, erasers, readers, and crosstalk between modifications"}, {"id": "e62c8d68-90c6-4730-b2be-7ae3ac95c27b", "type": "concept", "title": "PTM enrichment, detection, and functional validation"}]}, {"id": "5b969f4a-83a2-4a2f-95de-364bf1c784f2", "type": "subtopic", "title": "Forward and Reverse Chemical Genetics", "description": "Students use small molecules as conditional perturbations that can expose biological function.", "children": [{"id": "b10f0828-0183-4e85-beaa-d50877f322dc", "type": "concept", "title": "Phenotype-first screens and target-first perturbation"}, {"id": "fc11ae77-324b-473b-87f0-fc8a948300fd", "type": "concept", "title": "Resistance mutations, rescue experiments, analog-sensitive alleles, and synthetic lethality"}, {"id": "63ceff30-4258-41e3-af28-01dbddbb7992", "type": "concept", "title": "CRISPR, RNAi, and omics validation as companions to chemical probes"}]}]}, {"id": "9e4ed399-1bfb-4b3c-b7ef-bf885f3895c2", "type": "topic", "title": "Nucleic Acid Chemistry, Epigenetics, and Genome-Targeting Tools", "description": "Nucleic acids are information carriers and chemically tunable materials. Students learn how sequence, structure, modification, and delivery shape the design of tools for gene regulation and therapeutics.", "children": [{"id": "062cc44b-7caf-4446-b456-3e2307443a0c", "type": "subtopic", "title": "DNA and RNA Structure-Reactivity", "description": "The goal is to connect sequence and folding to molecular function.", "children": [{"id": "9e79c3e3-f6b1-4cbf-b6be-bd0542fc6141", "type": "concept", "title": "Duplexes, triplexes, G-quadruplexes, ribozymes, aptamers, and RNA secondary structure"}, {"id": "8801ece7-db61-4b1e-903e-23edaaec9b04", "type": "concept", "title": "Backbone, base, and sugar chemistry; hydrolysis and repair"}, {"id": "7f5b959c-7d73-4bd8-833b-a023b251a324", "type": "concept", "title": "Chemical probing methods such as SHAPE, DMS, and crosslinking"}]}, {"id": "8b8af063-d85e-4bfc-ae79-c3896114f7e6", "type": "subtopic", "title": "Epigenetic and Epitranscriptomic Chemistry", "description": "Students learn how chemical marks on nucleic acids regulate biological programs.", "children": [{"id": "00737166-c6fa-4fc6-9ad1-d906fcf84d71", "type": "concept", "title": "DNA methylation, hydroxymethylation, histone-code interfaces, and chromatin readers"}, {"id": "df1a31f1-df71-4796-b00e-fc53a51316eb", "type": "concept", "title": "RNA modifications including m6A, pseudouridine, and 5-methylcytidine"}, {"id": "da1774f9-c1ff-47ec-9fbe-b2ee9aeff9c3", "type": "concept", "title": "Mapping, perturbing, and interpreting modification function"}]}, {"id": "a1c63582-566b-4914-a7f7-4d3c47825752", "type": "subtopic", "title": "Genome and RNA-Targeting Technologies", "description": "This subtopic compares tools that alter or regulate genetic information.", "children": [{"id": "6e12e6e4-9c1b-498d-b120-00317cd87b5b", "type": "concept", "title": "CRISPR-Cas editing, base editing, prime editing, and guide RNA design"}, {"id": "09985b9a-3f42-4617-ad4b-db94f0d2016c", "type": "concept", "title": "Antisense oligonucleotides, siRNA, mRNA therapeutics, aptamers, and riboswitches"}, {"id": "c113c141-9f06-43d1-ab9e-2ef3c75632bf", "type": "concept", "title": "Delivery, off-target analysis, immunogenicity, and translational constraints"}]}]}, {"id": "fc808688-5c80-4808-ac6f-c5c0d02b93f1", "type": "topic", "title": "Carbohydrates, Lipids, Membranes, and Glycobiology", "description": "Many biological signals live outside the central dogma. This unit helps students understand chemically complex molecules that control recognition, compartmentalization, signaling, trafficking, and host-pathogen interactions.", "children": [{"id": "f7122c73-72d0-426b-87d5-f06a43689c94", "type": "subtopic", "title": "Carbohydrate Structure and Glycobiology", "description": "Students learn why glycans are information-rich despite not being template-encoded.", "children": [{"id": "d7b641c1-b2f1-447d-bd38-1cb46389acee", "type": "concept", "title": "Monosaccharide stereochemistry, linkages, branching, and glycosidic bond formation"}, {"id": "71f1e736-5a03-4577-bca5-9e1502fe9035", "type": "concept", "title": "Glycoproteins, glycolipids, proteoglycans, lectins, and glycan-binding proteins"}, {"id": "dc369f84-324f-4111-aa64-0da9f9cf21eb", "type": "concept", "title": "Metabolic oligosaccharide engineering and glycan imaging"}]}, {"id": "f54759a9-99ed-4c90-89b8-d15a14f9a647", "type": "subtopic", "title": "Lipid Chemistry and Membrane Organization", "description": "The point is to see membranes as active chemical environments.", "children": [{"id": "93397292-fccf-4546-8de4-d3740167c93c", "type": "concept", "title": "Fatty acids, phospholipids, sphingolipids, sterols, and lipid modifications"}, {"id": "c8eb24f9-b22d-4ac2-9395-66c5f62f5c06", "type": "concept", "title": "Bilayer properties, microdomains, curvature, trafficking, and organelle identity"}, {"id": "e3c60e07-0909-485c-85e0-8abe94b82e69", "type": "concept", "title": "Lipid signaling, lipidomics, and lipid-protein interactions"}]}, {"id": "176e5730-1d59-4fe4-965b-af6aa479f471", "type": "subtopic", "title": "Chemical Tools for Complex Biomolecules", "description": "Students learn strategies for molecules that are hard to sequence or amplify.", "children": [{"id": "d58b758b-43d2-4f52-a328-ab38ffa52027", "type": "concept", "title": "Chemoenzymatic synthesis and labeling"}, {"id": "883becc7-8ee0-443a-bdc0-19479bc3caee", "type": "concept", "title": "Mass spectrometry, enrichment, and separation strategies"}, {"id": "e5245923-387c-4957-b3b2-fd38866fa5f7", "type": "concept", "title": "Interpreting heterogeneous mixtures and site-specific modification data"}]}]}, {"id": "b54855ce-b180-4d70-8e55-4a2f646786eb", "type": "topic", "title": "Bioorthogonal Chemistry, Labeling, and Molecular Probes", "description": "Bioorthogonal chemistry is one of the field's signature toolkits. Students learn how reaction rate, selectivity, toxicity, tag size, and biological context determine whether a labeling strategy is useful.", "children": [{"id": "d6157210-896c-4014-967f-6b3b9d44dd07", "type": "subtopic", "title": "Bioorthogonal Reaction Families", "description": "Students compare reactions by compatibility, speed, and biological footprint.", "children": [{"id": "6056e892-369e-43f1-bd61-496230d6e6bd", "type": "concept", "title": "Azide-alkyne cycloaddition, strain-promoted cycloaddition, tetrazine ligation, Staudinger ligation, oxime and hydrazone ligation"}, {"id": "032bb1ec-8586-43d9-8d42-6f0b45bdb025", "type": "concept", "title": "Rate constants, catalyst requirements, steric effects, and aqueous performance"}, {"id": "9c810bdf-fe41-4703-8d69-56982ba0f052", "type": "concept", "title": "Reaction choice for cells, animals, fixed samples, and purified systems"}]}, {"id": "0cdfed0c-a6fb-4d2a-9bfc-a79a795d4044", "type": "subtopic", "title": "Probe Architecture", "description": "This subtopic teaches the design elements that turn chemistry into measurement.", "children": [{"id": "bb1877ba-b03d-4a76-a6ea-1daddef597a3", "type": "concept", "title": "Recognition element, reactive handle, linker, reporter, enrichment tag, and cleavable group"}, {"id": "c72c6eeb-4fbb-4e12-b63e-564693887a53", "type": "concept", "title": "Fluorogenic probes, turn-on designs, solvatochromic reporters, and photocaged tools"}, {"id": "ec37ca13-f9e5-4c39-bb39-92de26672229", "type": "concept", "title": "Balancing permeability, retention, stability, and signal-to-noise"}]}, {"id": "9a09a34c-682c-4a20-8a15-c59bb31ca9b7", "type": "subtopic", "title": "Metabolic and Proximity Labeling", "description": "Students learn how chemical reporters enter biological pathways or local neighborhoods.", "children": [{"id": "62dd3559-566f-42f7-9aa2-5bd4c17878ec", "type": "concept", "title": "Metabolic incorporation of azides and alkynes into glycans, lipids, proteins, and nucleic acids"}, {"id": "e9a6f002-960b-4de9-8860-d2f0cee16320", "type": "concept", "title": "APEX, BioID, TurboID, photocatalytic, and enzymatic proximity labeling"}, {"id": "86f32a29-aa94-4126-af36-8fb3f18585b3", "type": "concept", "title": "Spatial specificity, temporal resolution, and false-positive control"}]}]}, {"id": "d3b5e8a9-dad6-4df8-9794-6004e8b3561a", "type": "topic", "title": "Chemical Proteomics and Activity-Based Profiling", "description": "Chemical proteomics links molecules to proteins at scale. Students learn to design experiments that move from labeling to enriched samples, mass spectrometry data, target identification, and functional interpretation.", "children": [{"id": "3de9c44e-2f03-4fd9-986f-578f5c9cbbdd", "type": "subtopic", "title": "Activity-Based Protein Profiling", "description": "The point is to profile enzyme activity rather than protein abundance alone.", "children": [{"id": "914733c7-8e69-4c11-9317-f821e2c30a73", "type": "concept", "title": "Mechanism-linked probes for serine hydrolases, cysteine proteases, kinases, phosphatases, and oxidoreductases"}, {"id": "5b1cc9e1-c6f4-4abe-937d-cfbd30a6aa3e", "type": "concept", "title": "Competitive ABPP for ligand discovery and target engagement"}, {"id": "48101c94-71d9-49c3-88dc-5174455430b1", "type": "concept", "title": "Gel-based, fluorescence, and LC-MS/MS readouts"}]}, {"id": "f7aa717c-ddbe-4c71-b18c-6d000bf223b9", "type": "subtopic", "title": "Target Identification and Chemoproteomics", "description": "Students learn how to identify protein targets of bioactive small molecules.", "children": [{"id": "5dbbcccf-6905-4d50-a842-e54c0c49ec24", "type": "concept", "title": "Affinity capture, photoaffinity labeling, clickable probes, and thermal or stability-based methods"}, {"id": "b78100fe-4f45-4398-835f-c974b8addd84", "type": "concept", "title": "Controls: inactive analogs, competition, dose response, replicate design, and enrichment statistics"}, {"id": "60b9f431-2b5c-49a3-8d5f-f24ce8f22748", "type": "concept", "title": "Covalent ligand discovery and ligandable proteome mapping"}]}, {"id": "8f865eaa-0828-4308-924a-3bdf91c30207", "type": "subtopic", "title": "Mass Spectrometry Data Interpretation", "description": "This section introduces the practical logic behind proteomics evidence.", "children": [{"id": "a0f91eb7-5b82-4b1e-b4d5-eb849b84f91d", "type": "concept", "title": "Sample preparation, digestion, peptide identification, FDR, and protein inference"}, {"id": "8d65d935-fe97-4df5-ba76-0ed0e897c1a5", "type": "concept", "title": "Label-free, SILAC, TMT, DIA, and targeted proteomics"}, {"id": "33aeabb7-f370-4873-a75e-b92d3db493ce", "type": "concept", "title": "Site localization, occupancy, fold-change thresholds, and pathway interpretation"}]}]}, {"id": "ea8dd098-e215-4156-94b3-5055db622651", "type": "topic", "title": "Imaging, Biosensors, and Spatial-Temporal Control in Cells", "description": "Seeing and controlling biology in real time requires chemistry that survives complex cellular environments. This unit develops practical judgment about imaging probes, biosensors, light-controlled tools, and live-cell interpretation.", "children": [{"id": "c8bed46d-b8ad-4857-9fd9-9d6cb42e679f", "type": "subtopic", "title": "Fluorescence and Live-Cell Imaging", "description": "Students learn how optical readouts become biochemical evidence.", "children": [{"id": "65a99514-437b-4d83-8ca4-3d48409250b1", "type": "concept", "title": "Fluorophores, quantum yield, photostability, spectral overlap, and background"}, {"id": "14c0afa9-bd4f-4690-9178-b928181c4c09", "type": "concept", "title": "Confocal, super-resolution, FRET, FRAP, FLIM, and high-content imaging"}, {"id": "31b49f54-1c74-4950-b23a-dc0058b3aefc", "type": "concept", "title": "Controls for localization, phototoxicity, fixation artifacts, and signal quantitation"}]}, {"id": "052e7321-05fb-4c70-9744-253764783862", "type": "subtopic", "title": "Biosensors and Reporter Systems", "description": "This subtopic examines tools that report biological state.", "children": [{"id": "936d21f9-75e4-4bff-ac0f-438e1c688185", "type": "concept", "title": "Genetically encoded sensors, small-molecule sensors, turn-on probes, and luciferase reporters"}, {"id": "ca8d4144-519a-47e4-b9bc-105b2ab9fafa", "type": "concept", "title": "Redox, pH, calcium, kinase activity, metabolites, protease activity, and organelle-specific signals"}, {"id": "e1db9885-c59f-4bf2-9da8-adbd2ec45bf2", "type": "concept", "title": "Calibration, dynamic range, reversibility, and perturbation by the sensor itself"}]}, {"id": "61952fc2-f056-46e7-9d4e-b0d5958fe1f7", "type": "subtopic", "title": "Photochemical and Conditional Control", "description": "Students learn how timing and localization can change causal interpretation.", "children": [{"id": "d2c3b2c6-23e6-45bd-8837-8cad5f976713", "type": "concept", "title": "Photocaging, photoswitches, optogenetic-chemical hybrids, and targeted uncaging"}, {"id": "02c50da4-2d11-4196-a4e9-89c22d24d045", "type": "concept", "title": "Degron systems, PROTAC timing, chemically induced dimerization, and inducible localization"}, {"id": "28c0c57f-e4aa-4310-bab3-2bdd63cd5173", "type": "concept", "title": "Dose, light exposure, reversibility, and cellular stress controls"}]}]}, {"id": "7f229a82-8e79-4249-9dc0-7c9ae1d8de9b", "type": "topic", "title": "Natural Products, Medicinal Chemistry, and Target Engagement", "description": "Chemical biology and medicinal chemistry overlap when molecules become tools for mechanism and candidates for translation. Students learn to move from bioactivity to structure-activity reasoning, target engagement, and developability.", "children": [{"id": "5bfc8b91-b9af-456d-9ed1-bd88d594c7f8", "type": "subtopic", "title": "Natural Products as Chemical Biology Tools", "description": "Students examine why natural products often reveal important biology.", "children": [{"id": "cf8e0eef-ae94-45c8-b4b1-266659d52f4b", "type": "concept", "title": "Biosynthetic logic, privileged scaffolds, stereochemical complexity, and evolutionary selection"}, {"id": "825b9c41-3fef-487a-8d24-44cd6d61693a", "type": "concept", "title": "Mode-of-action discovery from phenotypic activity"}, {"id": "0bc04966-b188-4321-86ea-843968e6b8bf", "type": "concept", "title": "Semisynthesis, analog generation, and probe conversion"}]}, {"id": "3678f78b-f33b-40bc-99e8-f746019aa3e9", "type": "subtopic", "title": "Structure-Activity Relationships and Optimization", "description": "This section teaches disciplined interpretation of analog series.", "children": [{"id": "eeab7209-23c8-472c-8bc8-a16c738cfb78", "type": "concept", "title": "SAR tables, matched molecular pairs, potency, selectivity, permeability, and liabilities"}, {"id": "be404ae6-eabf-4d2d-8618-f956f0317572", "type": "concept", "title": "Lipophilicity, ionization, solubility, metabolism, and transporter effects"}, {"id": "0693dc71-d066-45e5-b8d4-f3b0202bff08", "type": "concept", "title": "Balancing tool-compound quality with therapeutic optimization"}]}, {"id": "36d08757-3fa2-4149-91a2-9b8a56874339", "type": "subtopic", "title": "Target Engagement and Pharmacology", "description": "The point is to prove that a molecule acts on the intended target in the relevant system.", "children": [{"id": "acf5adf6-0030-414c-8002-e6e9a3223090", "type": "concept", "title": "CETSA, NanoBRET, pull-down, competition, cellular thermal shift, and occupancy assays"}, {"id": "c6f8bdd9-2bd5-47c3-b017-9535e35311ee", "type": "concept", "title": "Cellular potency vs. biochemical potency"}, {"id": "ad643faf-eef1-41a4-b83e-dbe66dbb60ec", "type": "concept", "title": "On-target efficacy, off-target pharmacology, toxicity, and translational biomarkers"}]}]}, {"id": "8141d7f1-4caa-4671-a314-085dafacfef8", "type": "topic", "title": "Omics, Systems Chemical Biology, and Data Interpretation", "description": "Modern chemical biology often produces high-dimensional data. Students learn how to interpret systems-level signatures without losing chemical mechanism, experimental design, or statistical discipline.", "children": [{"id": "7cc83d33-7590-4306-b01e-40e66df248e7", "type": "subtopic", "title": "High-Throughput Screening and Phenotypic Profiling", "description": "Students learn how screening produces hypotheses and where it can mislead.", "children": [{"id": "705ec9d6-5c5c-4339-9ed2-74d906782458", "type": "concept", "title": "Assay development, Z-factor, dynamic range, counterscreens, and hit triage"}, {"id": "709169d9-c5b9-4c08-9aa5-45797b79c352", "type": "concept", "title": "Phenotypic profiling, image-based signatures, and mechanism clustering"}, {"id": "67d1dfd6-fd2a-469a-8208-608a14cf4520", "type": "concept", "title": "False positives, PAINS, aggregation, fluorescence artifacts, and cytotoxicity confounds"}]}, {"id": "4586c844-1c28-4199-a0da-e83676debeb3", "type": "subtopic", "title": "Multi-Omics Integration", "description": "This section shows how different datasets illuminate different layers of biology.", "children": [{"id": "19a40541-b53f-4e65-9579-231842436753", "type": "concept", "title": "Transcriptomics, proteomics, phosphoproteomics, metabolomics, lipidomics, glycomics, and chemoproteomics"}, {"id": "5d03a9e7-dc5d-4d7c-b72a-a4870142b6d7", "type": "concept", "title": "Pathway enrichment, network analysis, causal inference, and signature matching"}, {"id": "1ef40a79-3b02-49da-997c-90f0d0382cc9", "type": "concept", "title": "Batch effects, normalization, replicate design, and multiple testing"}]}, {"id": "741fff45-16e4-4a30-9b05-42c584913948", "type": "subtopic", "title": "Reproducible Computational Practice", "description": "Students learn enough data hygiene to make chemical biology conclusions auditable.", "children": [{"id": "a1bc0c1a-7448-4e5c-b8f6-6a0832ec50fb", "type": "concept", "title": "Data dictionaries, notebooks, version control, and workflow documentation"}, {"id": "e4d8d80f-7ff0-4172-aeda-6820599b1fc2", "type": "concept", "title": "Visualization choices for dose, time, pathway, and network data"}, {"id": "079a558f-73ef-4db0-8ad2-0beaa10c90c3", "type": "concept", "title": "FAIR data, metadata, and limits of public databases"}]}]}, {"id": "d75fb741-1fb3-444d-8bf1-a859a0503c54", "type": "topic", "title": "Translation, Ethics, Reproducibility, and Capstone Probe Design", "description": "The capstone asks students to behave like chemical biologists: identify a meaningful biological question, choose the right molecular strategy, anticipate failure modes, and justify the evidence needed for a convincing answer.", "children": [{"id": "5ea2ceb0-a44d-4c01-b698-eff8d11df969", "type": "subtopic", "title": "Tool Quality and Reproducibility", "description": "Students learn how to decide whether a probe is good enough to use or publish.", "children": [{"id": "3dd23dee-2008-4d1e-8a3c-ec130c62d456", "type": "concept", "title": "Potency, selectivity, permeability, stability, solubility, reversibility, and availability"}, {"id": "9f733cad-a241-4ddb-93f0-4274379c5ff9", "type": "concept", "title": "Chemical identity, purity, batch effects, negative controls, and orthogonal tools"}, {"id": "17c215ab-e423-4d15-a998-4a74deb4bd6f", "type": "concept", "title": "Reporting standards for probes, targets, assays, and datasets"}]}, {"id": "c9af51ac-c122-4bd1-a44f-9681c8816619", "type": "subtopic", "title": "Ethics, Safety, and Responsible Innovation", "description": "This section connects advanced molecular control to professional responsibility.", "children": [{"id": "0bdb69ca-861f-4886-8f35-ed0e77300bd6", "type": "concept", "title": "Biosafety, dual-use awareness, animal and human biospecimen ethics"}, {"id": "2a9a2fb0-b85f-440f-9578-d51e3d6191d4", "type": "concept", "title": "Equity in therapeutic translation and access to molecular technologies"}, {"id": "c0ade617-22f8-48ed-882f-e00404beef27", "type": "concept", "title": "Responsible communication of uncertain mechanistic and biomedical claims"}]}, {"id": "e79a28ee-7f3b-4681-8414-4dd0c734d808", "type": "subtopic", "title": "Capstone Probe or Study Design", "description": "Students integrate chemistry, biology, and data into a proposal that could guide real research.", "children": [{"id": "c11ce68b-67f9-417a-819d-347bf3e8d158", "type": "concept", "title": "Specific aims, biological rationale, chemical design, and experimental workflow"}, {"id": "f97e51ea-3c79-41d9-bfde-fe69a6668c45", "type": "concept", "title": "Validation plan, controls, anticipated results, and alternative strategies"}, {"id": "1f3d9830-edd5-4bd3-b546-ca228a95ecaa", "type": "concept", "title": "Peer review, revision, and presentation of limitations"}]}]}], "dbBacked": true}$cbbcjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'chemical-biology-and-bioorganic-chemistry'
);

update public.learning_paths
set
  title = 'Chemical Biology and Bioorganic Chemistry',
  goal = 'Chemical Biology and Bioorganic Chemistry',
  summary = 'This graduate course trains students to use chemical principles, molecular design, and quantitative biological evidence to understand and control living systems. It treats chemical biology and bioorganic chemistry as a single integrated practice: mechanisms and structure-reactivity relationships are used to design probes, perturb pathways, measure biological state, and evaluate therapeutic potential. The syllabus intentionally extends topics with modern structural biology, chemical proteomics, spatial-temporal cellular control, systems chemical biology, and reproducibility standards. These additions make the course suitable for a research-intensive MS Chemistry program and for students preparing for chemical biology, medicinal chemistry, biotechnology, pharmaceutical science, or interdisciplinary life-science research.',
  data = $cbbcjson${"slug": "chemical-biology-and-bioorganic-chemistry", "title": "Chemical Biology and Bioorganic Chemistry", "description": "This graduate course trains students to use chemical principles, molecular design, and quantitative biological evidence to understand and control living systems. It treats chemical biology and bioorganic chemistry as a single integrated practice: mechanisms and structure-reactivity relationships are used to design probes, perturb pathways, measure biological state, and evaluate therapeutic potential. The syllabus intentionally extends topics with modern structural biology, chemical proteomics, spatial-temporal cellular control, systems chemical biology, and reproducibility standards. These additions make the course suitable for a research-intensive MS Chemistry program and for students preparing for chemical biology, medicinal chemistry, biotechnology, pharmaceutical science, or interdisciplinary life-science research.", "topics": [{"id": "8aa8a3f3-6d40-459e-b97e-cb44d8d7eb80", "type": "topic", "title": "Foundations of Chemical Biology and Bioorganic Chemistry", "description": "This opening unit frames chemical biology as an experimental way of asking biological questions with molecular tools. Students learn what distinguishes probe design, perturbation, and mechanism-first thinking from descriptive biology or synthesis alone.", "children": [{"id": "1c7f4ca5-919a-4c71-b19f-45d2969c3016", "type": "subtopic", "title": "Field Scope and Research Questions", "description": "Students learn to convert broad biological problems into tractable molecular questions.", "children": [{"id": "e79da936-e1f1-45e2-895a-910a799aeccd", "type": "concept", "title": "Chemical biology vs. biochemistry, molecular biology, medicinal chemistry, and synthetic biology"}, {"id": "d856b58d-3676-45b1-94cd-230f8cee9543", "type": "concept", "title": "Probe, target, pathway, phenotype, and mechanism as working units"}, {"id": "2b0e1bf2-4937-4702-86b2-2caf7c557e2e", "type": "concept", "title": "Choosing when a chemical approach is more powerful than a genetic or purely biochemical approach"}]}, {"id": "76c09871-9024-4d57-852b-7586525846a8", "type": "subtopic", "title": "Bioorganic Logic in Living Systems", "description": "This subtopic connects structure and reactivity to the behavior of biomolecules in water, cells, and tissues.", "children": [{"id": "22dc89ea-668b-42ae-8774-57d34e33e721", "type": "concept", "title": "Functional groups and reaction manifolds common in biomolecules"}, {"id": "d7cde8ca-82ea-4407-aff1-3b4a9bc39a83", "type": "concept", "title": "Selectivity, kinetics, reversibility, and compatibility with biological media"}, {"id": "65689326-cabb-4106-92d9-62675ded7578", "type": "concept", "title": "How pH, solvation, compartment, and concentration change chemical outcomes"}]}, {"id": "790378a5-db4a-46c1-8bef-2ff28708b077", "type": "subtopic", "title": "Experimental Design and Evidence Standards", "description": "Students practice judging whether a chemical tool really supports the biological claim being made.", "children": [{"id": "aceb97ea-0458-491d-8719-04b65534cb07", "type": "concept", "title": "Controls for activity, specificity, toxicity, and localization"}, {"id": "81724f50-1db3-4621-b435-da42e1abf604", "type": "concept", "title": "Dose-response, time-course, rescue, and orthogonal validation"}, {"id": "4383bf45-9869-4a72-8991-4c209633b8ba", "type": "concept", "title": "Common failure modes: promiscuity, assay interference, aggregation, and off-target biology"}]}]}, {"id": "9c978524-0ff0-4c48-b364-ee817fa58bd9", "type": "topic", "title": "Biomolecular Structure, Recognition, and Noncovalent Interactions", "description": "Chemical biology depends on understanding molecular recognition with enough precision to design experiments. This unit teaches students to read structure, binding, and dynamics as a design language for probes and interventions.", "children": [{"id": "7567e1dc-76e3-4bc5-97bc-306a61058c35", "type": "subtopic", "title": "Protein Structure and Dynamics", "description": "The goal is to see proteins as flexible chemical systems rather than static cartoons.", "children": [{"id": "be9131bd-27e7-4c5d-aa64-f09ac5abba93", "type": "concept", "title": "Primary through quaternary structure and intrinsically disordered regions"}, {"id": "4960465e-d667-4602-b23c-c6eb4d460fd3", "type": "concept", "title": "Active sites, allostery, conformational selection, and induced fit"}, {"id": "d0314c4d-ba3c-48f3-a5d1-f55d9fe2fedc", "type": "concept", "title": "Using RCSB Protein Data Bank structures to reason about function"}]}, {"id": "60ef59f0-7e3b-4c1d-898b-484dcbbb6053", "type": "subtopic", "title": "Ligand Binding and Molecular Recognition", "description": "Students learn the forces that make binding strong, selective, and biologically meaningful.", "children": [{"id": "951a1bd9-1488-414e-80a6-fb61edb7f14a", "type": "concept", "title": "Hydrogen bonding, electrostatics, hydrophobic effects, cation-pi and pi-stacking interactions"}, {"id": "134c68c7-b03f-4319-aa0a-2d49fdf57804", "type": "concept", "title": "Affinity, residence time, cooperativity, and competition"}, {"id": "1fbbbfff-25c9-403f-9d3f-cd1cde692253", "type": "concept", "title": "Thermodynamic vs. kinetic control in protein-ligand systems"}]}, {"id": "7ba69a52-df79-4de0-9791-5ea80a7c551f", "type": "subtopic", "title": "Structural Methods for Chemical Biology", "description": "This section explains how structural evidence is produced and what its limits are.", "children": [{"id": "25bd82ce-5638-40f8-b1eb-6091c5bb4436", "type": "concept", "title": "X-ray crystallography, NMR, cryo-EM, mass spectrometry, and computational models"}, {"id": "bb893eea-493e-4e13-a00f-2643052b748b", "type": "concept", "title": "Resolution, model uncertainty, occupancy, and alternate conformations"}, {"id": "09f5151e-c5e1-4a1d-a21c-996360afb493", "type": "concept", "title": "Using structural data without overclaiming biological mechanism"}]}]}, {"id": "d0d3fa63-e9e5-4900-8b78-e2db70c1195d", "type": "topic", "title": "Enzyme Mechanisms, Catalysis, and Bioorganic Reactivity", "description": "Enzymes are central objects in bioorganic chemistry because they reveal how biological systems accelerate and control reactions. Students learn to connect kinetic data, mechanistic hypotheses, and inhibitor design.", "children": [{"id": "97519fe7-38ca-4ce4-9f69-19f7e068fb05", "type": "subtopic", "title": "Kinetics and Catalytic Mechanisms", "description": "Students learn the quantitative vocabulary needed to interpret enzyme behavior.", "children": [{"id": "f36ce2dc-dabf-4705-8632-701aba711013", "type": "concept", "title": "Michaelis-Menten analysis, steady-state assumptions, kcat, KM, and catalytic efficiency"}, {"id": "b1af27b5-0eb7-42fb-8932-a28025cd2d89", "type": "concept", "title": "Pre-steady-state kinetics, isotope effects, pH-rate profiles, and saturation behavior"}, {"id": "32fcdb1b-7042-42d4-9148-237e2b8e82d3", "type": "concept", "title": "General acid-base, covalent, metal-ion, proximity, and electrostatic catalysis"}]}, {"id": "b6507fc4-40c3-431e-871d-a7af2e7d066b", "type": "subtopic", "title": "Inhibition and Mechanism-Based Inactivators", "description": "The point is to distinguish reversible modulation from covalent or time-dependent enzyme capture.", "children": [{"id": "bdec1794-e9fc-471c-a946-0c09413c7382", "type": "concept", "title": "Competitive, noncompetitive, uncompetitive, mixed, tight-binding, and slow-binding inhibition"}, {"id": "7f1557a7-7f0c-489e-ab1f-d218c442e843", "type": "concept", "title": "Covalent inhibitors, suicide substrates, electrophile tuning, and warhead selectivity"}, {"id": "97de081d-3de3-4c20-8d76-704671cafabe", "type": "concept", "title": "Interpreting IC50, Ki, kinact/KI, and target engagement data"}]}, {"id": "a1412aff-5fd1-4e42-b49f-d4f0640adb93", "type": "subtopic", "title": "Transition-State and Cofactor Chemistry", "description": "This subtopic shows how enzyme chemistry can inspire both probes and therapeutics.", "children": [{"id": "3e5e7b51-beec-49ac-9eb1-2fb43d37eb30", "type": "concept", "title": "Transition-state analogs and catalytic antibodies"}, {"id": "45d55814-a478-45b7-a2e1-4059552bef10", "type": "concept", "title": "PLP, NAD(P)H, flavins, biotin, thiamine pyrophosphate, SAM, and metal cofactors"}, {"id": "7db045c9-dbc7-4dc2-8f39-dc8051271a1c", "type": "concept", "title": "Radical, redox, methyl-transfer, acyl-transfer, and group-transfer mechanisms"}]}]}, {"id": "169fede5-5302-40cc-b942-606291a7c3d1", "type": "topic", "title": "Protein Chemistry, Modification, and Chemical Genetics", "description": "Proteins are both targets and tools in chemical biology. This unit builds fluency in modifying proteins, perturbing functions, and using chemical-genetic logic to assign mechanism.", "children": [{"id": "8996863f-f4de-4100-a21a-540ca6250da9", "type": "subtopic", "title": "Protein Modification and Bioconjugation", "description": "Students learn how to install chemical functionality while preserving biological meaning.", "children": [{"id": "5c73d207-f306-4946-abc8-bb5c1c8b9619", "type": "concept", "title": "Lysine, cysteine, N-terminus, tyrosine, methionine, and unnatural amino acid labeling"}, {"id": "fde1c745-3c89-4e16-ac5b-e16bb10f2b32", "type": "concept", "title": "Site-selective vs. residue-selective strategies and stoichiometry control"}, {"id": "22d56650-14b8-471e-acfd-8d3663271179", "type": "concept", "title": "Stability, activity retention, purification, and analytical confirmation"}]}, {"id": "d0f2359d-20e7-4c16-ba7d-2d737ebfa70c", "type": "subtopic", "title": "Post-Translational Modifications", "description": "This subtopic treats PTMs as dynamic chemical signals that regulate protein function.", "children": [{"id": "23eea951-1ed6-4d3a-b80e-ad07d82b03e7", "type": "concept", "title": "Phosphorylation, acetylation, methylation, ubiquitination, SUMOylation, glycosylation, lipidation, and redox PTMs"}, {"id": "1980e417-dc56-4e5e-aec5-24d9e55e0670", "type": "concept", "title": "Writers, erasers, readers, and crosstalk between modifications"}, {"id": "e62c8d68-90c6-4730-b2be-7ae3ac95c27b", "type": "concept", "title": "PTM enrichment, detection, and functional validation"}]}, {"id": "5b969f4a-83a2-4a2f-95de-364bf1c784f2", "type": "subtopic", "title": "Forward and Reverse Chemical Genetics", "description": "Students use small molecules as conditional perturbations that can expose biological function.", "children": [{"id": "b10f0828-0183-4e85-beaa-d50877f322dc", "type": "concept", "title": "Phenotype-first screens and target-first perturbation"}, {"id": "fc11ae77-324b-473b-87f0-fc8a948300fd", "type": "concept", "title": "Resistance mutations, rescue experiments, analog-sensitive alleles, and synthetic lethality"}, {"id": "63ceff30-4258-41e3-af28-01dbddbb7992", "type": "concept", "title": "CRISPR, RNAi, and omics validation as companions to chemical probes"}]}]}, {"id": "9e4ed399-1bfb-4b3c-b7ef-bf885f3895c2", "type": "topic", "title": "Nucleic Acid Chemistry, Epigenetics, and Genome-Targeting Tools", "description": "Nucleic acids are information carriers and chemically tunable materials. Students learn how sequence, structure, modification, and delivery shape the design of tools for gene regulation and therapeutics.", "children": [{"id": "062cc44b-7caf-4446-b456-3e2307443a0c", "type": "subtopic", "title": "DNA and RNA Structure-Reactivity", "description": "The goal is to connect sequence and folding to molecular function.", "children": [{"id": "9e79c3e3-f6b1-4cbf-b6be-bd0542fc6141", "type": "concept", "title": "Duplexes, triplexes, G-quadruplexes, ribozymes, aptamers, and RNA secondary structure"}, {"id": "8801ece7-db61-4b1e-903e-23edaaec9b04", "type": "concept", "title": "Backbone, base, and sugar chemistry; hydrolysis and repair"}, {"id": "7f5b959c-7d73-4bd8-833b-a023b251a324", "type": "concept", "title": "Chemical probing methods such as SHAPE, DMS, and crosslinking"}]}, {"id": "8b8af063-d85e-4bfc-ae79-c3896114f7e6", "type": "subtopic", "title": "Epigenetic and Epitranscriptomic Chemistry", "description": "Students learn how chemical marks on nucleic acids regulate biological programs.", "children": [{"id": "00737166-c6fa-4fc6-9ad1-d906fcf84d71", "type": "concept", "title": "DNA methylation, hydroxymethylation, histone-code interfaces, and chromatin readers"}, {"id": "df1a31f1-df71-4796-b00e-fc53a51316eb", "type": "concept", "title": "RNA modifications including m6A, pseudouridine, and 5-methylcytidine"}, {"id": "da1774f9-c1ff-47ec-9fbe-b2ee9aeff9c3", "type": "concept", "title": "Mapping, perturbing, and interpreting modification function"}]}, {"id": "a1c63582-566b-4914-a7f7-4d3c47825752", "type": "subtopic", "title": "Genome and RNA-Targeting Technologies", "description": "This subtopic compares tools that alter or regulate genetic information.", "children": [{"id": "6e12e6e4-9c1b-498d-b120-00317cd87b5b", "type": "concept", "title": "CRISPR-Cas editing, base editing, prime editing, and guide RNA design"}, {"id": "09985b9a-3f42-4617-ad4b-db94f0d2016c", "type": "concept", "title": "Antisense oligonucleotides, siRNA, mRNA therapeutics, aptamers, and riboswitches"}, {"id": "c113c141-9f06-43d1-ab9e-2ef3c75632bf", "type": "concept", "title": "Delivery, off-target analysis, immunogenicity, and translational constraints"}]}]}, {"id": "fc808688-5c80-4808-ac6f-c5c0d02b93f1", "type": "topic", "title": "Carbohydrates, Lipids, Membranes, and Glycobiology", "description": "Many biological signals live outside the central dogma. This unit helps students understand chemically complex molecules that control recognition, compartmentalization, signaling, trafficking, and host-pathogen interactions.", "children": [{"id": "f7122c73-72d0-426b-87d5-f06a43689c94", "type": "subtopic", "title": "Carbohydrate Structure and Glycobiology", "description": "Students learn why glycans are information-rich despite not being template-encoded.", "children": [{"id": "d7b641c1-b2f1-447d-bd38-1cb46389acee", "type": "concept", "title": "Monosaccharide stereochemistry, linkages, branching, and glycosidic bond formation"}, {"id": "71f1e736-5a03-4577-bca5-9e1502fe9035", "type": "concept", "title": "Glycoproteins, glycolipids, proteoglycans, lectins, and glycan-binding proteins"}, {"id": "dc369f84-324f-4111-aa64-0da9f9cf21eb", "type": "concept", "title": "Metabolic oligosaccharide engineering and glycan imaging"}]}, {"id": "f54759a9-99ed-4c90-89b8-d15a14f9a647", "type": "subtopic", "title": "Lipid Chemistry and Membrane Organization", "description": "The point is to see membranes as active chemical environments.", "children": [{"id": "93397292-fccf-4546-8de4-d3740167c93c", "type": "concept", "title": "Fatty acids, phospholipids, sphingolipids, sterols, and lipid modifications"}, {"id": "c8eb24f9-b22d-4ac2-9395-66c5f62f5c06", "type": "concept", "title": "Bilayer properties, microdomains, curvature, trafficking, and organelle identity"}, {"id": "e3c60e07-0909-485c-85e0-8abe94b82e69", "type": "concept", "title": "Lipid signaling, lipidomics, and lipid-protein interactions"}]}, {"id": "176e5730-1d59-4fe4-965b-af6aa479f471", "type": "subtopic", "title": "Chemical Tools for Complex Biomolecules", "description": "Students learn strategies for molecules that are hard to sequence or amplify.", "children": [{"id": "d58b758b-43d2-4f52-a328-ab38ffa52027", "type": "concept", "title": "Chemoenzymatic synthesis and labeling"}, {"id": "883becc7-8ee0-443a-bdc0-19479bc3caee", "type": "concept", "title": "Mass spectrometry, enrichment, and separation strategies"}, {"id": "e5245923-387c-4957-b3b2-fd38866fa5f7", "type": "concept", "title": "Interpreting heterogeneous mixtures and site-specific modification data"}]}]}, {"id": "b54855ce-b180-4d70-8e55-4a2f646786eb", "type": "topic", "title": "Bioorthogonal Chemistry, Labeling, and Molecular Probes", "description": "Bioorthogonal chemistry is one of the field's signature toolkits. Students learn how reaction rate, selectivity, toxicity, tag size, and biological context determine whether a labeling strategy is useful.", "children": [{"id": "d6157210-896c-4014-967f-6b3b9d44dd07", "type": "subtopic", "title": "Bioorthogonal Reaction Families", "description": "Students compare reactions by compatibility, speed, and biological footprint.", "children": [{"id": "6056e892-369e-43f1-bd61-496230d6e6bd", "type": "concept", "title": "Azide-alkyne cycloaddition, strain-promoted cycloaddition, tetrazine ligation, Staudinger ligation, oxime and hydrazone ligation"}, {"id": "032bb1ec-8586-43d9-8d42-6f0b45bdb025", "type": "concept", "title": "Rate constants, catalyst requirements, steric effects, and aqueous performance"}, {"id": "9c810bdf-fe41-4703-8d69-56982ba0f052", "type": "concept", "title": "Reaction choice for cells, animals, fixed samples, and purified systems"}]}, {"id": "0cdfed0c-a6fb-4d2a-9bfc-a79a795d4044", "type": "subtopic", "title": "Probe Architecture", "description": "This subtopic teaches the design elements that turn chemistry into measurement.", "children": [{"id": "bb1877ba-b03d-4a76-a6ea-1daddef597a3", "type": "concept", "title": "Recognition element, reactive handle, linker, reporter, enrichment tag, and cleavable group"}, {"id": "c72c6eeb-4fbb-4e12-b63e-564693887a53", "type": "concept", "title": "Fluorogenic probes, turn-on designs, solvatochromic reporters, and photocaged tools"}, {"id": "ec37ca13-f9e5-4c39-bb39-92de26672229", "type": "concept", "title": "Balancing permeability, retention, stability, and signal-to-noise"}]}, {"id": "9a09a34c-682c-4a20-8a15-c59bb31ca9b7", "type": "subtopic", "title": "Metabolic and Proximity Labeling", "description": "Students learn how chemical reporters enter biological pathways or local neighborhoods.", "children": [{"id": "62dd3559-566f-42f7-9aa2-5bd4c17878ec", "type": "concept", "title": "Metabolic incorporation of azides and alkynes into glycans, lipids, proteins, and nucleic acids"}, {"id": "e9a6f002-960b-4de9-8860-d2f0cee16320", "type": "concept", "title": "APEX, BioID, TurboID, photocatalytic, and enzymatic proximity labeling"}, {"id": "86f32a29-aa94-4126-af36-8fb3f18585b3", "type": "concept", "title": "Spatial specificity, temporal resolution, and false-positive control"}]}]}, {"id": "d3b5e8a9-dad6-4df8-9794-6004e8b3561a", "type": "topic", "title": "Chemical Proteomics and Activity-Based Profiling", "description": "Chemical proteomics links molecules to proteins at scale. Students learn to design experiments that move from labeling to enriched samples, mass spectrometry data, target identification, and functional interpretation.", "children": [{"id": "3de9c44e-2f03-4fd9-986f-578f5c9cbbdd", "type": "subtopic", "title": "Activity-Based Protein Profiling", "description": "The point is to profile enzyme activity rather than protein abundance alone.", "children": [{"id": "914733c7-8e69-4c11-9317-f821e2c30a73", "type": "concept", "title": "Mechanism-linked probes for serine hydrolases, cysteine proteases, kinases, phosphatases, and oxidoreductases"}, {"id": "5b1cc9e1-c6f4-4abe-937d-cfbd30a6aa3e", "type": "concept", "title": "Competitive ABPP for ligand discovery and target engagement"}, {"id": "48101c94-71d9-49c3-88dc-5174455430b1", "type": "concept", "title": "Gel-based, fluorescence, and LC-MS/MS readouts"}]}, {"id": "f7aa717c-ddbe-4c71-b18c-6d000bf223b9", "type": "subtopic", "title": "Target Identification and Chemoproteomics", "description": "Students learn how to identify protein targets of bioactive small molecules.", "children": [{"id": "5dbbcccf-6905-4d50-a842-e54c0c49ec24", "type": "concept", "title": "Affinity capture, photoaffinity labeling, clickable probes, and thermal or stability-based methods"}, {"id": "b78100fe-4f45-4398-835f-c974b8addd84", "type": "concept", "title": "Controls: inactive analogs, competition, dose response, replicate design, and enrichment statistics"}, {"id": "60b9f431-2b5c-49a3-8d5f-f24ce8f22748", "type": "concept", "title": "Covalent ligand discovery and ligandable proteome mapping"}]}, {"id": "8f865eaa-0828-4308-924a-3bdf91c30207", "type": "subtopic", "title": "Mass Spectrometry Data Interpretation", "description": "This section introduces the practical logic behind proteomics evidence.", "children": [{"id": "a0f91eb7-5b82-4b1e-b4d5-eb849b84f91d", "type": "concept", "title": "Sample preparation, digestion, peptide identification, FDR, and protein inference"}, {"id": "8d65d935-fe97-4df5-ba76-0ed0e897c1a5", "type": "concept", "title": "Label-free, SILAC, TMT, DIA, and targeted proteomics"}, {"id": "33aeabb7-f370-4873-a75e-b92d3db493ce", "type": "concept", "title": "Site localization, occupancy, fold-change thresholds, and pathway interpretation"}]}]}, {"id": "ea8dd098-e215-4156-94b3-5055db622651", "type": "topic", "title": "Imaging, Biosensors, and Spatial-Temporal Control in Cells", "description": "Seeing and controlling biology in real time requires chemistry that survives complex cellular environments. This unit develops practical judgment about imaging probes, biosensors, light-controlled tools, and live-cell interpretation.", "children": [{"id": "c8bed46d-b8ad-4857-9fd9-9d6cb42e679f", "type": "subtopic", "title": "Fluorescence and Live-Cell Imaging", "description": "Students learn how optical readouts become biochemical evidence.", "children": [{"id": "65a99514-437b-4d83-8ca4-3d48409250b1", "type": "concept", "title": "Fluorophores, quantum yield, photostability, spectral overlap, and background"}, {"id": "14c0afa9-bd4f-4690-9178-b928181c4c09", "type": "concept", "title": "Confocal, super-resolution, FRET, FRAP, FLIM, and high-content imaging"}, {"id": "31b49f54-1c74-4950-b23a-dc0058b3aefc", "type": "concept", "title": "Controls for localization, phototoxicity, fixation artifacts, and signal quantitation"}]}, {"id": "052e7321-05fb-4c70-9744-253764783862", "type": "subtopic", "title": "Biosensors and Reporter Systems", "description": "This subtopic examines tools that report biological state.", "children": [{"id": "936d21f9-75e4-4bff-ac0f-438e1c688185", "type": "concept", "title": "Genetically encoded sensors, small-molecule sensors, turn-on probes, and luciferase reporters"}, {"id": "ca8d4144-519a-47e4-b9bc-105b2ab9fafa", "type": "concept", "title": "Redox, pH, calcium, kinase activity, metabolites, protease activity, and organelle-specific signals"}, {"id": "e1db9885-c59f-4bf2-9da8-adbd2ec45bf2", "type": "concept", "title": "Calibration, dynamic range, reversibility, and perturbation by the sensor itself"}]}, {"id": "61952fc2-f056-46e7-9d4e-b0d5958fe1f7", "type": "subtopic", "title": "Photochemical and Conditional Control", "description": "Students learn how timing and localization can change causal interpretation.", "children": [{"id": "d2c3b2c6-23e6-45bd-8837-8cad5f976713", "type": "concept", "title": "Photocaging, photoswitches, optogenetic-chemical hybrids, and targeted uncaging"}, {"id": "02c50da4-2d11-4196-a4e9-89c22d24d045", "type": "concept", "title": "Degron systems, PROTAC timing, chemically induced dimerization, and inducible localization"}, {"id": "28c0c57f-e4aa-4310-bab3-2bdd63cd5173", "type": "concept", "title": "Dose, light exposure, reversibility, and cellular stress controls"}]}]}, {"id": "7f229a82-8e79-4249-9dc0-7c9ae1d8de9b", "type": "topic", "title": "Natural Products, Medicinal Chemistry, and Target Engagement", "description": "Chemical biology and medicinal chemistry overlap when molecules become tools for mechanism and candidates for translation. Students learn to move from bioactivity to structure-activity reasoning, target engagement, and developability.", "children": [{"id": "5bfc8b91-b9af-456d-9ed1-bd88d594c7f8", "type": "subtopic", "title": "Natural Products as Chemical Biology Tools", "description": "Students examine why natural products often reveal important biology.", "children": [{"id": "cf8e0eef-ae94-45c8-b4b1-266659d52f4b", "type": "concept", "title": "Biosynthetic logic, privileged scaffolds, stereochemical complexity, and evolutionary selection"}, {"id": "825b9c41-3fef-487a-8d24-44cd6d61693a", "type": "concept", "title": "Mode-of-action discovery from phenotypic activity"}, {"id": "0bc04966-b188-4321-86ea-843968e6b8bf", "type": "concept", "title": "Semisynthesis, analog generation, and probe conversion"}]}, {"id": "3678f78b-f33b-40bc-99e8-f746019aa3e9", "type": "subtopic", "title": "Structure-Activity Relationships and Optimization", "description": "This section teaches disciplined interpretation of analog series.", "children": [{"id": "eeab7209-23c8-472c-8bc8-a16c738cfb78", "type": "concept", "title": "SAR tables, matched molecular pairs, potency, selectivity, permeability, and liabilities"}, {"id": "be404ae6-eabf-4d2d-8618-f956f0317572", "type": "concept", "title": "Lipophilicity, ionization, solubility, metabolism, and transporter effects"}, {"id": "0693dc71-d066-45e5-b8d4-f3b0202bff08", "type": "concept", "title": "Balancing tool-compound quality with therapeutic optimization"}]}, {"id": "36d08757-3fa2-4149-91a2-9b8a56874339", "type": "subtopic", "title": "Target Engagement and Pharmacology", "description": "The point is to prove that a molecule acts on the intended target in the relevant system.", "children": [{"id": "acf5adf6-0030-414c-8002-e6e9a3223090", "type": "concept", "title": "CETSA, NanoBRET, pull-down, competition, cellular thermal shift, and occupancy assays"}, {"id": "c6f8bdd9-2bd5-47c3-b017-9535e35311ee", "type": "concept", "title": "Cellular potency vs. biochemical potency"}, {"id": "ad643faf-eef1-41a4-b83e-dbe66dbb60ec", "type": "concept", "title": "On-target efficacy, off-target pharmacology, toxicity, and translational biomarkers"}]}]}, {"id": "8141d7f1-4caa-4671-a314-085dafacfef8", "type": "topic", "title": "Omics, Systems Chemical Biology, and Data Interpretation", "description": "Modern chemical biology often produces high-dimensional data. Students learn how to interpret systems-level signatures without losing chemical mechanism, experimental design, or statistical discipline.", "children": [{"id": "7cc83d33-7590-4306-b01e-40e66df248e7", "type": "subtopic", "title": "High-Throughput Screening and Phenotypic Profiling", "description": "Students learn how screening produces hypotheses and where it can mislead.", "children": [{"id": "705ec9d6-5c5c-4339-9ed2-74d906782458", "type": "concept", "title": "Assay development, Z-factor, dynamic range, counterscreens, and hit triage"}, {"id": "709169d9-c5b9-4c08-9aa5-45797b79c352", "type": "concept", "title": "Phenotypic profiling, image-based signatures, and mechanism clustering"}, {"id": "67d1dfd6-fd2a-469a-8208-608a14cf4520", "type": "concept", "title": "False positives, PAINS, aggregation, fluorescence artifacts, and cytotoxicity confounds"}]}, {"id": "4586c844-1c28-4199-a0da-e83676debeb3", "type": "subtopic", "title": "Multi-Omics Integration", "description": "This section shows how different datasets illuminate different layers of biology.", "children": [{"id": "19a40541-b53f-4e65-9579-231842436753", "type": "concept", "title": "Transcriptomics, proteomics, phosphoproteomics, metabolomics, lipidomics, glycomics, and chemoproteomics"}, {"id": "5d03a9e7-dc5d-4d7c-b72a-a4870142b6d7", "type": "concept", "title": "Pathway enrichment, network analysis, causal inference, and signature matching"}, {"id": "1ef40a79-3b02-49da-997c-90f0d0382cc9", "type": "concept", "title": "Batch effects, normalization, replicate design, and multiple testing"}]}, {"id": "741fff45-16e4-4a30-9b05-42c584913948", "type": "subtopic", "title": "Reproducible Computational Practice", "description": "Students learn enough data hygiene to make chemical biology conclusions auditable.", "children": [{"id": "a1bc0c1a-7448-4e5c-b8f6-6a0832ec50fb", "type": "concept", "title": "Data dictionaries, notebooks, version control, and workflow documentation"}, {"id": "e4d8d80f-7ff0-4172-aeda-6820599b1fc2", "type": "concept", "title": "Visualization choices for dose, time, pathway, and network data"}, {"id": "079a558f-73ef-4db0-8ad2-0beaa10c90c3", "type": "concept", "title": "FAIR data, metadata, and limits of public databases"}]}]}, {"id": "d75fb741-1fb3-444d-8bf1-a859a0503c54", "type": "topic", "title": "Translation, Ethics, Reproducibility, and Capstone Probe Design", "description": "The capstone asks students to behave like chemical biologists: identify a meaningful biological question, choose the right molecular strategy, anticipate failure modes, and justify the evidence needed for a convincing answer.", "children": [{"id": "5ea2ceb0-a44d-4c01-b698-eff8d11df969", "type": "subtopic", "title": "Tool Quality and Reproducibility", "description": "Students learn how to decide whether a probe is good enough to use or publish.", "children": [{"id": "3dd23dee-2008-4d1e-8a3c-ec130c62d456", "type": "concept", "title": "Potency, selectivity, permeability, stability, solubility, reversibility, and availability"}, {"id": "9f733cad-a241-4ddb-93f0-4274379c5ff9", "type": "concept", "title": "Chemical identity, purity, batch effects, negative controls, and orthogonal tools"}, {"id": "17c215ab-e423-4d15-a998-4a74deb4bd6f", "type": "concept", "title": "Reporting standards for probes, targets, assays, and datasets"}]}, {"id": "c9af51ac-c122-4bd1-a44f-9681c8816619", "type": "subtopic", "title": "Ethics, Safety, and Responsible Innovation", "description": "This section connects advanced molecular control to professional responsibility.", "children": [{"id": "0bdb69ca-861f-4886-8f35-ed0e77300bd6", "type": "concept", "title": "Biosafety, dual-use awareness, animal and human biospecimen ethics"}, {"id": "2a9a2fb0-b85f-440f-9578-d51e3d6191d4", "type": "concept", "title": "Equity in therapeutic translation and access to molecular technologies"}, {"id": "c0ade617-22f8-48ed-882f-e00404beef27", "type": "concept", "title": "Responsible communication of uncertain mechanistic and biomedical claims"}]}, {"id": "e79a28ee-7f3b-4681-8414-4dd0c734d808", "type": "subtopic", "title": "Capstone Probe or Study Design", "description": "Students integrate chemistry, biology, and data into a proposal that could guide real research.", "children": [{"id": "c11ce68b-67f9-417a-819d-347bf3e8d158", "type": "concept", "title": "Specific aims, biological rationale, chemical design, and experimental workflow"}, {"id": "f97e51ea-3c79-41d9-bfde-fe69a6668c45", "type": "concept", "title": "Validation plan, controls, anticipated results, and alternative strategies"}, {"id": "1f3d9830-edd5-4bd3-b546-ca228a95ecaa", "type": "concept", "title": "Peer review, revision, and presentation of limitations"}]}]}], "dbBacked": true}$cbbcjson$::jsonb,
